import dataclasses
import re
import warnings
from typing import Any, AnyStr, Iterable, Iterator, Match as HitHint, Optional, Pattern as CompiledHint, Tuple, Union

class RuleBase(object):
    __slots__ = ('decision',)

    def __init__(self, decision: Optional[bool]) -> None:
        self.decision = decision

    def match(self, paths: Iterable[str]) -> Iterator[str]:
        warnings.warn('{cls.__module__}.{cls.__qualname__}.match() is legacy; iterate using match_path().'.format(cls=self.__class__), DeprecationWarning, stacklevel=2)
        for path in paths:
            if self.match_path(path) is not None:
                yield path

    def match_path(self, path: str) -> Optional[Any]:
        raise NotImplementedError('{cls.__module__}.{cls.__qualname__} needs a match_path implementation.'.format(cls=self.__class__))

class TextRule(RuleBase):
    __slots__ = ('expression', 'compiled')

    def __init__(self, expression: Union[AnyStr, CompiledHint, None], decision: Optional[bool]=None) -> None:
        if isinstance(expression, (str, bytes)):
            assert decision is None, f'decision {decision!r} requires no override for expression {expression!r} supplied as text.'
            compiled, decision = self.compile_text(expression)
            if decision is not None:
                compiled = re.compile(compiled)
        elif expression is not None and hasattr(expression, 'match'):
            compiled = expression
        elif expression is None:
            assert decision is None, f'decision {decision!r} requires no override for expression {expression!r} supplied as disabled.'
        else:
            raise TypeError(f'expression {expression!r} must be text, a compiled matcher, or disabled.')
        super(TextRule, self).__init__(decision)
        self.expression: Union[AnyStr, CompiledHint, None] = expression
        self.compiled: CompiledHint = compiled

    def __eq__(self, candidate: 'TextRule') -> bool:
        if isinstance(candidate, TextRule):
            return self.decision == candidate.decision and self.compiled == candidate.compiled
        else:
            return NotImplemented

    def match_path(self, path: str) -> Optional['Hit']:
        if self.decision is not None:
            match = self.compiled.match(path)
            if match is not None:
                return Hit(match)
        return None

    @classmethod
    def compile_text(cls, expression: str) -> Tuple[str, bool]:
        return (expression, True)

@dataclasses.dataclass()
class Hit(object):
    __slots__ = ('match',)
    match: HitHint
